/**
 * @file sim.h
 * @brief LVGL 模拟器公共接口（显示 / 输入 / 截图 / 场景）。
 */

#ifndef SIM_H
#define SIM_H

#include <stdbool.h>
#include <stdint.h>

#include "lvgl.h"

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    int width;          /**< 设备像素宽，默认 240 */
    int height;         /**< 设备像素高，默认 320（设备原生竖屏） */
    int scale;          /**< 窗口放大倍数，默认 2 */
    const char *title;  /**< 窗口标题 */
    bool headless;      /**< 不建窗口，跑固定帧数后截图 */
    const char *shot;   /**< headless 下的 PNG 输出路径 */
    int frames;         /**< headless 跑多少帧，默认 30 */
    const char *ui_tour; /**< `ui` 场景巡页截图目录（NULL = 关闭，默认） */
    int tour_frames;    /**< 巡页每页等待帧数，默认 90 */
} sim_cfg_t;

/* ── 显示 ──────────────────────────────────────────────────────── */

/** 建窗口（或 headless 下什么都不建）。返回 false 表示失败。 */
bool sim_display_init(const sim_cfg_t *cfg);

/** 把 LVGL 刷出来的一块 RGB565 送到窗口/影子帧缓冲。 */
void sim_display_present(const lv_area_t *area, const uint16_t *px, int stride_px);

/** 处理一次 X 事件；返回 false 表示窗口被关掉。 */
bool sim_display_pump(void);

void sim_display_shutdown(void);

/** headless 下的整帧影子缓冲（RGB565，w*h）。 */
const uint16_t *sim_display_shadow(int *w, int *h);

/** 显示初始化后调用：把 flush_cb / indev 挂到 LVGL 上。 */
void sim_lvgl_bind(void);

/** 键盘焦点组（场景里把可聚焦控件加进来）。 */
lv_group_t *sim_input_group(void);

/** 中文字体（FreeType + 系统 TTF），按字号缓存；失败时退回内置子集。 */
lv_font_t *sim_font_cjk(int px);

/** 同上，可指定斜体（水名习惯用斜体）。 */
lv_font_t *sim_font_cjk_style(int px, bool italic);

/* ── 截图 ──────────────────────────────────────────────────────── */

/** RGB565 帧缓冲 → PNG。 */
bool sim_png_write(const char *path, const uint16_t *fb, int w, int h);

/* ── 场景 ──────────────────────────────────────────────────────── */

typedef void (*sim_scene_fn_t)(lv_obj_t *scr, const sim_cfg_t *cfg);

typedef struct {
    const char *name;
    const char *desc;
    sim_scene_fn_t create;
} sim_scene_t;

const sim_scene_t *sim_scene_find(const char *name);
void sim_scene_list(void);

void scene_demo_create(lv_obj_t *scr, const sim_cfg_t *cfg);
void scene_vmap_create(lv_obj_t *scr, const sim_cfg_t *cfg);

/**
 * @brief 启动 vendor/my_vendor 里真实的自行车 UI（`ui` 场景）。
 *
 * 只有 `SIM_WITH_UI=ON`（默认）编进来时才有定义；它自己接管屏幕，场景函数
 * 调完立刻返回。实现见 ui_port/ui_boot.c。
 */
void sim_ui_start(void);

/* ── `ui` 场景巡页（模拟器专用；只在 SIM_WITH_UI 下有定义） ────── */

/** 记录巡页参数；必须在 sim_ui_start() 之前调用。dir=NULL 关闭巡页。 */
void sim_ui_tour_configure(const char *dir, int frames);
/** 开机序列结束后启动巡页（ui_boot.c 末尾调用；未配置时为空操作）。 */
void sim_ui_tour_start(void);
/** 巡页结束（或失败）后返回 true；headless 主循环据此退出。 */
bool sim_ui_tour_done(void);
/** 是否配置了巡页（未配置时主循环行为完全不变）。 */
bool sim_ui_tour_enabled(void);

#ifdef __cplusplus
}
#endif

#endif /* SIM_H */
=== main.c ===
/**
 * @file main.c
 * @brief lvgl_sim 入口：参数解析 → LVGL 初始化 → 场景 → 主循环。
 *
 *   ./lvgl_sim                       # 默认 demo 场景，240x320 @2x 窗口
 *   ./lvgl_sim --scene vmap          # vmap 底图 mock
 *   ./lvgl_sim --scale 3             # 放大到 3 倍
 *   ./lvgl_sim --headless --frames 40 --shot out.png
 */

#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "sim.h"

uint32_t sim_tick_ms(void);

static uint32_t s_vtick;

static uint32_t vtick_get(void)
{
    return s_vtick;
}

static const char *const kUsageLines[] = {
    "用法: lvgl_sim [选项]",
    "  -s, --scene NAME    场景（demo | vmap | ui），默认 demo",
    "  -S, --size WxH      设备分辨率，默认 240x320（设备原生竖屏）",
    "  -k, --scale N       窗口放大倍数，默认 2",
    "  -H, --headless      不建窗口，跑固定帧数",
    "  -f, --frames N      headless 帧数，默认 30",
    "  -o, --shot PATH     headless 截图输出 PNG",
    "  -t, --title TEXT    窗口标题",
    "      --ui-tour DIR   巡页模式（仅 --scene ui）：逐页/逐主题截图到 DIR",
    "      --tour-frames N 巡页每页等待帧数，默认 90",
    "  -l, --list          列出所有场景",
    "  -h, --help          本帮助",
    NULL,
};

static void usage(void)
{
    for (int i = 0; kUsageLines[i]; i++) {
        puts(kUsageLines[i]);
    }
}

int main(int argc, char **argv)
{
    sim_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.width = 240;
    cfg.height = 320;   /* 设备原生竖屏：状态栏 24 + 页面 296 */
    cfg.scale = 2;
    cfg.frames = 30;
    cfg.tour_frames = 90;
    cfg.title = "lvgl_sim";

    const char *scene_name = "demo";
    bool list_only = false;

    enum {
        OPT_UI_TOUR = 256,
        OPT_TOUR_FRAMES,
    };

    static const struct option long_opts[] = {
        { "scene",    required_argument, 0, 's' },
        { "size",     required_argument, 0, 'S' },
        { "scale",    required_argument, 0, 'k' },
        { "headless", no_argument,       0, 'H' },
        { "frames",   required_argument, 0, 'f' },
        { "shot",     required_argument, 0, 'o' },
        { "title",    required_argument, 0, 't' },
        { "ui-tour",  required_argument, 0, OPT_UI_TOUR },
        { "tour-frames", required_argument, 0, OPT_TOUR_FRAMES },
        { "list",     no_argument,       0, 'l' },
        { "help",     no_argument,       0, 'h' },
        { NULL, 0, NULL, 0 },
    };

    int c;
    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
        switch (c) {
            case 's': scene_name = optarg; break;
            case 'S':
                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
                    fprintf(stderr, "bad --size\n");
                    return 2;
                }
                break;
            case 'k': cfg.scale = atoi(optarg); break;
            case 'H': cfg.headless = true; break;
            case 'f': cfg.frames = atoi(optarg); break;
            case 'o': cfg.shot = optarg; break;
            case 't': cfg.title = optarg; break;
            case OPT_UI_TOUR: cfg.ui_tour = optarg; break;
            case OPT_TOUR_FRAMES: cfg.tour_frames = atoi(optarg); break;
            case 'l': list_only = true; break;
            case 'h': usage(); return 0;
            default: usage(); return 2;
        }
    }

    if (list_only) {
        sim_scene_list();
        return 0;
    }

    const sim_scene_t *scene = sim_scene_find(scene_name);
    if (!scene) {
        fprintf(stderr, "unknown scene\n");
        sim_scene_list();
        return 2;
    }

    lv_init();
    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);

    if (!sim_display_init(&cfg)) {
        return 1;
    }
    sim_lvgl_bind();

    scene->create(lv_screen_active(), &cfg);
    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");

    if (cfg.ui_tour != NULL && cfg.tour_frames <= 0) {
        cfg.tour_frames = 90;
    }

    if (cfg.headless) {
        /* 巡页模式下帧数由巡页状态机自己决定，这里只给一个死循环保护。
         * 只有 `ui` 场景会真正启用巡页（见 scenes.c）；其它场景带 --ui-tour
         * 也完全按原来的 --frames 跑。 */
        int frames = cfg.frames;

#ifdef SIM_WITH_UI
        const bool tour = sim_ui_tour_enabled();

        if (tour) {
            frames = 6000;
        }
#endif
        for (int i = 0; i < frames; i++) {
            s_vtick += 16;
            lv_timer_handler();
#ifdef SIM_WITH_UI
            if (tour && sim_ui_tour_done()) {
                break;
            }
#endif
        }
        if (cfg.shot) {
            int w = 0;
            int h = 0;
            const uint16_t *fb = sim_display_shadow(&w, &h);

            if (!sim_png_write(cfg.shot, fb, w, h)) {
                fprintf(stderr, "failed to write png\n");
                sim_display_shutdown();
                return 1;
            }
            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
        }
    } else {
        while (sim_display_pump()) {
            uint32_t idle = lv_timer_handler();

#ifdef SIM_WITH_UI
            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
                break;
            }
#endif
            if (idle < 1) {
                idle = 1;
            }
            if (idle > 16) {
                idle = 16;
            }
            usleep(idle * 1000);
        }
    }

    sim_display_shutdown();
    return 0;
}

/**
 * @file vmap_style.h
 * @brief vmap style 模块。
 */

#ifndef VMAP_STYLE_H
#define VMAP_STYLE_H

#include "vmap_format.h"
#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

#define VMAP_STYLE_ROAD_CLASSES 8

/*
 * 板端只有 z14 瓦片（`docs/map/STYLE.md` §7「z14 单层数据」），放大只是把 z14
 * 几何按 `scale` 线性放大 —— 于是"当前 zoom = 14 + log2(scale)"。可见性判定
 * 按 STYLE.md §3 的"从哪个 zoom 开始画"折成 **scale 阈值**（2^(z-14)）：
 *   道路  z6 / z9 / z11 / z12.5 / z13.5 / z14.5
 *         ⇒ scale 0.004 / 0.031 / 0.125 / 0.354 / 0.707 / 1.414
 *   用地  z12.5 / z15 ⇒ scale 0.354 / 2.0
 * 设备默认 scale = 1.69（VMAP_DEFAULT_SCALE）⇒ service 已出、商务/工业不出。
 */
#define VMAP_STYLE_ZOOM 14u

/** @brief scale × 1000（整数比较用；scale 是 z14 瓦片的线性倍率）。 */
static inline int32_t vmap_style_scale_milli(float scale)
{
    if (!(scale > 0.0f)) {
        return 1000;
    }

    return (int32_t)(scale * 1000.0f + 0.5f);
}

typedef enum {
    VMAP_STYLE_CLASSIC = 0,
    VMAP_STYLE_NAV,
    /** @brief 白天户外盘（terrain）：暖底、绿更重、棕步道（STYLE.md §2 terrain）。 */
    VMAP_STYLE_OUTDOOR,
    /** @brief 夜间盘（night）：深色底 + 深色道路（STYLE.md §2 night）。 */
    VMAP_STYLE_NIGHT,
    VMAP_STYLE_COUNT
} vmap_style_id_t;

typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
    /** @brief 芯宽，**1/10 设备像素**（z14 1× 基准，STYLE.md §3）。
     *
     * 原来这里是整像素，表达不了 4.2 / 3.6 / 3.0 / 2.6 / 2.2 / 1.7 / 1.4 的
     * 宽度阶梯（整像素会把相邻两级压成同一级）。唯一读取点是
     * `vmap_render.c` 的 `road_core_px()`，用整数换算成设备像素，不引入浮点。
     */
    uint8_t w;
    uint8_t cr;     /**< 壳色 r（STYLE.md §2「路壳」；path 无壳，等于芯色） */
    uint8_t cg;     /**< 壳色 g */
    uint8_t cb;     /**< 壳色 b */
} vmap_style_road_t;

/**
 * @brief 该等级道路在当前缩放下是否绘制（STYLE.md §3 最后一列）。
 * @param cls  道路等级（VMAP_ROAD_*）。
 * @param scale z14 瓦片的线性倍率（`vmap_view_set_scale`）。
 * @return true 绘制。
 */
static inline bool vmap_style_road_visible(uint8_t cls, float scale)
{
    static const uint16_t k_min_scale_milli[VMAP_STYLE_ROAD_CLASSES] = {
        0u, 4u, 31u, 125u, 354u, 707u, 1414u, 707u,
    };

    if (cls == 0u || cls >= VMAP_STYLE_ROAD_CLASSES) {
        return false;
    }

    return vmap_style_scale_milli(scale) >= (int32_t)k_min_scale_milli[cls];
}

/**
 * @brief 该用地类型在当前缩放下是否绘制（STYLE.md §5.4）。
 * @param attr  VMAP_LAND_*。
 * @param scale z14 瓦片的线性倍率。
 * @return true 绘制。
 */
static inline bool vmap_style_land_visible(uint8_t attr, float scale)
{
    switch (attr) {
    case VMAP_LAND_COMMERCIAL:
    case VMAP_LAND_INDUSTRIAL:
        /* z15 起：设备默认 scale 1.69 < 2.0 ⇒ 商务/工业默认不出现。 */
        return vmap_style_scale_milli(scale) >= 2000;
    case VMAP_LAND_RESIDENTIAL:
    case VMAP_LAND_EDU:
    case VMAP_LAND_PARK:
        return vmap_style_scale_milli(scale) >= 354;      /* z12.5 */
    default:
        /* 未知类型保持旧行为（按住宅色画出来），不要静默丢数据。 */
        return true;
    }
}

typedef struct {
    const char * name;

    /* Map canvas (RGB888 → rasterizer converts to RGB565). */
    uint8_t bg_r;
    uint8_t bg_g;
    uint8_t bg_b;
    uint8_t forest_r;
    uint8_t forest_g;
    uint8_t forest_b;
    uint8_t land_res_r;
    uint8_t land_res_g;
    uint8_t land_res_b;
    uint8_t land_com_r;
    uint8_t land_com_g;
    uint8_t land_com_b;
    uint8_t land_edu_r;
    uint8_t land_edu_g;
    uint8_t land_edu_b;
    uint8_t land_park_r;
    uint8_t land_park_g;
    uint8_t land_park_b;
    uint8_t water_r;
    uint8_t water_g;
    uint8_t water_b;
    uint8_t road_case_r;
    uint8_t road_case_g;
    uint8_t road_case_b;
    uint8_t road_case_extra;
    uint8_t waterway_r;
    uint8_t waterway_g;
    uint8_t waterway_b;
    uint8_t waterway_w;
    vmap_style_road_t road[VMAP_STYLE_ROAD_CLASSES];

    /* Track overlay on map canvas, above labels. */
    bool track_speed_gradient;
    uint8_t track_r;
    uint8_t track_g;
    uint8_t track_b;
    uint8_t track_line_w;
    uint8_t km_badge_r;
    uint8_t km_badge_g;
    uint8_t km_badge_b;

    /* Map labels (0xRRGGBB). */
    uint32_t lbl_place;
    uint32_t lbl_water;
    uint32_t lbl_poi;
    uint32_t lbl_road;
    /** @brief 标签描边 halo 色（STYLE.md §2「描边 halo」：日光白、夜间近黑）。 */
    uint32_t lbl_halo;
    /** @brief 描边不透明度（0–255）。 */
    uint8_t  lbl_halo_opa;

    /* LVGL chrome (0xRRGGBB, opa 0–255). */
    uint32_t ui_root_bg;
    uint32_t ui_status_bg;
    uint8_t  ui_status_opa;
    uint32_t ui_title_text;
    uint32_t ui_accent;
    uint32_t ui_rec;
    uint32_t ui_panel_bg;
    uint8_t  ui_panel_opa;
    uint32_t ui_panel_border;
    uint8_t  ui_panel_border_opa;
    uint32_t ui_speed_text;
    uint32_t ui_heading_text;
    uint32_t ui_dist_text;
    uint32_t ui_toast_bg;
    uint8_t  ui_toast_opa;
    uint32_t ui_toast_text;
    bool     ui_navi_arrow_dark;
} vmap_style_t;

#define VMAP_STYLE_RGB565(r, g, b) \
    ((uint16_t)(((((uint16_t)(r)) & 0xF8u) << 8) | \
                ((((uint16_t)(g)) & 0xFCu) << 3) | \
                (((uint16_t)(b)) >> 3)))

/**
 * @brief vmap style rgb565。
 */
uint16_t vmap_style_rgb565(uint8_t r, uint8_t g, uint8_t b);
/**
 * @brief 当前主题背景 RGB565。
 */
uint16_t vmap_style_bg565(void);

/**
 * @brief vmap style count。
 * @return 请求的值。
 */
unsigned vmap_style_count(void);
/**
 * @brief vmap style get id。
 * @return 请求的值。
 */
vmap_style_id_t vmap_style_get_id(void);
/**
 * @brief vmap style current。
 */
const vmap_style_t * vmap_style_current(void);
/**
 * @brief vmap style get。
 * @return 请求的值。
 */
const vmap_style_t * vmap_style_get(vmap_style_id_t id);
/**
 * @brief vmap style name。
 */
const char * vmap_style_name(vmap_style_id_t id);

/**
 * @brief vmap style set id。
 * @return 请求的值。
 */
bool vmap_style_set_id(vmap_style_id_t id);
/**
 * @brief vmap style set。
 */
bool vmap_style_set(vmap_style_id_t id);
/**
 * @brief vmap style set next。
 */
bool vmap_style_set_next(void);
/**
 * @brief vmap style set by name。
 */
bool vmap_style_set_by_name(const char * name);

typedef void (*vmap_style_changed_cb_t)(vmap_style_id_t id, void * user_data);
/**
 * @brief vmap style set changed cb。
 */
void vmap_style_set_changed_cb(vmap_style_changed_cb_t cb, void * user_data);
/** @deprecated 请优先使用 lv_pm_theme_set + lv_pm_set_theme_changed。 */

#ifdef __cplusplus
}
#endif

#endif /* VMAP_STYLE_H */

/**
 * @file vmap_style.c
 * @brief vmap style 模块。
 */

#include "vmap_style.h"

#include "vmap_format.h"
#include <string.h>

#define RS(r, g, b, w) { (uint8_t)(r), (uint8_t)(g), (uint8_t)(b), (uint8_t)(w), 0, 0, 0 }
#define RSC(r, g, b, w, cr, cg, cb) \
    { (uint8_t)(r), (uint8_t)(g), (uint8_t)(b), (uint8_t)(w), \
      (uint8_t)(cr), (uint8_t)(cg), (uint8_t)(cb) }

/*
 * 调色板口径：`docs/map/STYLE.md` §2（唯一权威）。四份设备盘对应：
 *   classic ← paper（纸面，默认）   nav ← bright（冷白）
 *   outdoor ← terrain（白天户外）   night ← night（夜间）
 *
 * 道路一律"壳 + 芯"：芯色 r/g/b，壳色 cr/cg/cb；w 是 1/10 px 的芯宽（§3）。
 * 等级靠宽度阶梯分层，不靠七种颜色 —— 芯色只有"琥珀（主干）→ 近白（支路）"两族。
 */
static const vmap_style_t g_vmap_styles[VMAP_STYLE_COUNT] = {
    [VMAP_STYLE_CLASSIC] = {
        .name = "classic",
        /* paper：暖白纸面 #F4F1E8 */
        .bg_r = 244, .bg_g = 241, .bg_b = 232,
        .forest_r = 203, .forest_g = 224, .forest_b = 188,       /* #CBE0BC */
        .land_res_r = 239, .land_res_g = 234, .land_res_b = 222, /* #EFEADE land1 */
        /* land2/3 在结构里共用一个槽（下面 §2 的 land2/land3 色差 1~2 级）；
         * 设备 z14 两者都不画（§5.4），取 land3 #EFECE4。 */
        .land_com_r = 239, .land_com_g = 236, .land_com_b = 228,
        .land_edu_r = 249, .land_edu_g = 242, .land_edu_b = 218, /* #F9F2DA land4 */
        .land_park_r = 216, .land_park_g = 232, .land_park_b = 202, /* #D8E8CA land5 */
        .water_r = 169, .water_g = 208, .water_b = 232,          /* #A9D0E8 */
        /* 遗留的全局壳色：新路径按 class 取 cr/cg/cb，这里只做兜底。 */
        .road_case_r = 202, .road_case_g = 196, .road_case_b = 182,
        .road_case_extra = 1,
        .waterway_r = 147, .waterway_g = 194, .waterway_b = 218, /* #93C2DA */
        .waterway_w = 2,
        .road = {
            [0] = RS(0, 0, 0, 0),
            /* 芯 / 壳 / 芯宽（1/10 px，§3） */
            [VMAP_ROAD_MOTORWAY]   = RSC(247, 200, 115, 42, 206, 143,  51), /* #F7C873 / #CE8F33 */
