#define SIM_UI_TICK_MS 10u

static bool s_started;
static bicycle_mtp_ui_t s_mtp_ui;

/**
 * @brief 板端 while(1) 的主体（去掉 usleep 与 watchdog/性能探针）。
 *
 * 顺序照抄 `bicycle_c_main.c`：ctl 队列 → 传感器 → 演示 →（帧后）主题重活。
 */
static void sim_ui_loop_body(void)
{
    map_page_t *page = lvgl_page_map();

    bicycle_mtp_ui_run(&s_mtp_ui);
    bicycle_ui_ctl_poll(page);
    bicycle_runtime_sync_companion_sensors();
    bicycle_demo_poll();

    /* 这两步在板端放在 lv_timer_handler() 之后（帧后做换主题的重活），
     * 在定时器回调里已经是"帧内"，顺序等价。 */
    helm_theme_poll_apply();
    lv_pm_theme_poll_styles();

    if (page && !lvgl_page_is_usb_transfer()) {
        map_page_debug_snap(page);
    }
}

static void ui_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;
    sim_ui_loop_body();
}

/* 板端 `vmap_map_catalog.c` 把地图目录存进 **64 字节** 的 `char map_dir[64]`，
 * PC 上那条 mkfs 绝对路径（90+ 字符）会被截断 ⇒ 找不到瓦片、地图空白。
 * 所以给一个短路径，指向设备真正烧的那份网格包。 */
static void ensure_short_map_path(void)
{
    const char *short_path = "/tmp/vmap";
    struct stat st;

    if (lstat(short_path, &st) == 0) {
        return;
    }
    if (symlink(SIM_VMAP_REAL_DIR, short_path) != 0) {
        fprintf(stderr, "sim_ui: 建不了 %s -> %s（地图会空白）\n",
                short_path, SIM_VMAP_REAL_DIR);
    }
}

void sim_ui_start(void)
{
    lv_display_t *disp;
    lv_obj_t *scr;
    lv_timer_t *refr;
    map_page_t *page;
    int rc;

    if (s_started) {
        return;
    }
    s_started = true;

    ensure_short_map_path();

    disp = lv_display_get_default();
    if (disp == NULL) {
        fprintf(stderr, "sim_ui: no display (sim_lvgl_bind 没跑？)\n");
        return;
    }

    printf("sim_ui: boot start %dx%d\n", (int)lv_display_get_horizontal_resolution(disp),
           (int)lv_display_get_vertical_resolution(disp));

    /* ── 与 bicycle_c_main.c 完全一致的前奏 ────────────────────────────── */
    scr = lv_display_get_screen_active(disp);
    lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    /* 开机时先不让 LVGL 刷：板端是为了把 2SFBL 的像素留在屏上。 */
    lv_display_enable_invalidation(disp, false);
    refr = lv_display_get_refr_timer(disp);
    if (refr) {
        lv_timer_pause(refr);
    }

    lv_display_set_antialiasing(disp, true);

    /* CONFIG_MYVENDOR_LCD_DISP 的 flush done 回调是板级 /dev/lcd0 的东西，模拟器
     * 的 flush_cb 自己调 lv_display_flush_ready()，不需要也不该再注册。 */

    /* 按键：PC 上 lv_port_buttons.c 整份被 `#if defined(__NuttX__)` 关掉，
     * 这里调用的是它自己的空实现，与板端保持同一调用点。 */
    lv_port_buttons_init();

    lvgl_page_init();

    rc = lvgl_page_open_boot_sequence();
    if (rc != 0) {
        fprintf(stderr, "sim_ui: lvgl_page_open_boot_sequence failed (%d)\n", rc);
        return;
    }

    if (!myvendor_is_factory()) {
        startup_page_sync_boot();
    }

    printf("sim_ui: pages registered, splash open\n");

    /* splash / 工厂页用编译进去的 helm 点阵字体，先画一帧再谈 TTF / MTP / vmap */
    lv_display_enable_invalidation(disp, true);
    refr = lv_display_get_refr_timer(disp);
    if (refr) {
        lv_timer_resume(refr);
    }
    scr = lv_display_get_screen_active(disp);
    lv_obj_invalidate(scr);
    lv_obj_update_layout(scr);
    lv_refr_now(disp);

    page = lvgl_page_map();
    if (!page) {
        printf("sim_ui: splash active, LiveMap loads under Startup\n");
    }

    /* MTP：模拟器没有 USB 端点，不启 worker（myvendor_mtp_init 是板级线程），
     * 只初始化 UI 侧状态机，让页面切换逻辑照常跑。 */
    bicycle_mtp_ui_init(&s_mtp_ui);

    lvgl_page_set_app_started(true);

    printf("sim_ui: app started, ui_ctl ready\n");
    bicycle_ui_ctl_ready();
    bicycle_ui_ctl_sync_state();

    /* 板端 while(1) 的等价物 */
    lv_timer_create(ui_tick_cb, SIM_UI_TICK_MS, NULL);

    /* 巡页（--ui-tour）：也是 LVGL timer，未配置时什么都不做。 */
    sim_ui_tour_start();

    printf("sim_ui: boot done (10 ms tick running)\n");
}

