{"content": "/**
 * @file vmap_layer_probe.c
 * @brief 模拟器专用的 vmap 分层开关实现（见 vmap_layer_probe.h 的用法）。
 */

#include "vmap_layer_probe.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "vmap_format.h"

/** 隐藏位图：bit(layer) 与 bit(8 + cls)；bit0 = "全部隐藏"。 */
static unsigned s_mask;
/** bit(layer) = 该层被**显式保留**（SIM_VMAP_SHOW 模式）。 */
static unsigned s_keep;
static bool s_show_mode;
static bool s_inited;

static bool token_match(const char * tok, size_t len, const char * lit)
{
    return strlen(lit) == len && strncmp(tok, lit, len) == 0;
}

static void apply_token(const char * tok, size_t len, bool keep)
{
    struct {
        const char * name;
        int id;
    } layers[] = {
        { "water", VMAP_LAYER_WATER },
        { "forest", VMAP_LAYER_FOREST },
        { "waterway", VMAP_LAYER_WATERWAY },
        { "land", VMAP_LAYER_LAND },
        { "road", VMAP_LAYER_ROAD },
    };
    int cls_lo = 0;
    int cls_hi = 0;
    int i;

    if (len == 0) {
        return;
    }
    if (token_match(tok, len, "all")) {
        int l;

        for (l = 0; l < VMAP_LAYER_MAX; l++) {
            if (keep) {
                s_keep |= 1u << l;
            } else {
                s_mask |= 1u << l;
            }
        }
        if (!keep) {
            s_mask |= 1u;                 /* 全部隐藏 */
        }
        return;
    }
    if (token_match(tok, len, "path")) {
        cls_lo = cls_hi = VMAP_ROAD_PATH;
    } else if (token_match(tok, len, "road46")) {
        cls_lo = VMAP_ROAD_TERTIARY;
        cls_hi = VMAP_ROAD_SERVICE;
    } else if (token_match(tok, len, "road1-3")) {
        cls_lo = VMAP_ROAD_MOTORWAY;
        cls_hi = VMAP_ROAD_SECONDARY;
    } else if (token_match(tok, len, "road")) {
        cls_lo = VMAP_ROAD_MOTORWAY;
        cls_hi = VMAP_ROAD_PATH;
    }

    if (cls_lo > 0) {
        for (i = cls_lo; i <= cls_hi; i++) {
            if (keep) {
                s_keep |= 1u << (8 + i);
            } else {
                s_mask |= 1u << (8 + i);
            }
        }
        /* 只关某个 class 时，ROAD 层本身仍要画，不能整层关。 */
        return;
    }

    for (i = 0; i < (int)(sizeof(layers) / sizeof(layers[0])); i++) {
        if (token_match(tok, len, layers[i].name)) {
            if (keep) {
                s_keep |= 1u << layers[i].id;
            } else {
                s_mask |= 1u << layers[i].id;
            }
            return;
        }
    }
}

static void scan_env(const char * env, const char * fallback, bool keep)
{
    const char * s = env;

    if (s == NULL || s[0] == '\0') {
        s = fallback;
    }
    while (s != NULL && s[0] != '\0') {
        const char * comma = strchr(s, ',');
        size_t len = comma ? (size_t)(comma - s) : strlen(s);

        while (len > 0 && (s[0] == ' ' || s[0] == '\t')) {
            s++;
            len--;
        }
        while (len > 0 && (s[len - 1] == ' ' || s[len - 1] == '\t')) {
            len--;
        }
        apply_token(s, len, keep);
        s = comma ? comma + 1 : NULL;
    }
}

static void probe_init(void)
{
    const char * hide;
    const char * show;

    if (s_inited) {
        return;
    }
    s_inited = true;

    hide = getenv("SIM_VMAP_HIDE");
    show = getenv("SIM_VMAP_SHOW");
    if (show != NULL && show[0] != '\0') {
        s_show_mode = true;
        scan_env(show, NULL, true);
    } else {
        scan_env(hide, NULL, false);
    }
    if (s_mask != 0u || s_keep != 0u) {
        fprintf(stderr, "sim_vmap: layer probe on (hide mask=0x%x keep=0x%x)\n",
            s_mask, s_keep);
    }
}

bool sim_vmap_layer_on(int layer)
{
    probe_init();

    if (s_mask == 0u && s_keep == 0u) {
        return true;
    }
    if (s_mask & 1u) {
        return false;                     /* all */
    }
    if (layer < 0 || layer >= VMAP_LAYER_MAX) {
        return true;
    }
    if (s_show_mode) {
        return (s_keep & (1u << layer)) != 0u;
    }
    return (s_mask & (1u << layer)) == 0u;
}

bool sim_vmap_cls_on(int cls)
{
    probe_init();

    if (s_mask == 0u && s_keep == 0u) {
        return true;
    }
    if (cls < 1 || cls >= VMAP_STYLE_ROAD_CLASSES) {
        return true;
    }
    if (s_mask & 1u) {
        return false;
    }
    if (s_show_mode) {
        const bool keep_any_cls = (s_keep & 0x7f00u) != 0u;

        return !keep_any_cls || ((s_keep & (1u << (8 + cls))) != 0u);
    }
    return (s_mask & (1u << (8 + cls))) == 0u;
}

bool sim_vmap_any_hidden(void)
{
    probe_init();

    return s_mask != 0u || s_keep != 0u;
}
